// Segment identity and bookkeeping. A segment is one finalized utterance; its
// id is generated by the speaker and travels with it, so both sides (and any
// resend after a reconnect) refer to the same utterance.

import type { SegmentRecord } from './events';

export function newSegmentId(): string {
  return globalThis.crypto?.randomUUID?.() ?? `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

/** Insertion-ordered set with a size cap; evicts the oldest entry. */
export class BoundedSet<T> {
  private items = new Set<T>();
  constructor(private readonly max: number) {}
  has(v: T): boolean {
    return this.items.has(v);
  }
  add(v: T): void {
    if (this.items.has(v)) return;
    if (this.items.size >= this.max) this.items.delete(this.items.values().next().value as T);
    this.items.add(v);
  }
  get size(): number {
    return this.items.size;
  }
}

export class SegmentLedger {
  private records = new Map<string, SegmentRecord>();
  private seenPeerIds: BoundedSet<string>;
  private seq = 0;

  constructor(
    private readonly maxRecords = 500,
    maxSeen = 500
  ) {
    this.seenPeerIds = new BoundedSet(maxSeen);
  }

  nextSeq(): number {
    return this.seq++;
  }

  /**
   * Records an inbound segment id. Returns false if it was already seen — the
   * caller must then drop it (it is a resend after reconnect, or a replay).
   */
  acceptPeerSegment(id: string): boolean {
    if (this.seenPeerIds.has(id)) return false;
    this.seenPeerIds.add(id);
    return true;
  }

  upsert(record: SegmentRecord): void {
    this.records.delete(record.id);
    this.records.set(record.id, record);
    while (this.records.size > this.maxRecords) {
      this.records.delete(this.records.keys().next().value as string);
    }
  }

  update(id: string, patch: Partial<SegmentRecord>): SegmentRecord | undefined {
    const rec = this.records.get(id);
    if (!rec) return undefined;
    const next = { ...rec, ...patch };
    this.records.set(id, next);
    return next;
  }

  get(id: string): SegmentRecord | undefined {
    return this.records.get(id);
  }

  list(): SegmentRecord[] {
    return [...this.records.values()];
  }

  get size(): number {
    return this.records.size;
  }
}
